n_error = 0
n_total = 0
error_models = {}
for ds in DATASETS:
    for mid in ALL_MODELS:
        if mid not in clean[ds]:
            continue
        for s in clean[ds][mid]:
            n_total += 1
            w = s.get('winner')
            if w is None or s.get('error'):
                n_error += 1
                error_models[mid] = error_models.get(mid, 0) + 1
        for atk in ATTACKS:
            if mid not in attacked[ds][atk]:
                continue
            for s in attacked[ds][atk][mid]:
                n_total += 1
                w = s.get('winner')
                if w is None or s.get('error'):
                    n_error += 1
                    error_models[mid] = error_models.get(mid, 0) + 1

print(f'Total scores: {n_total}')
print(f'Error scores: {n_error}')
print(f'Error rate: {n_error/n_total:.4%}')
print('By model:')
for mid, cnt in sorted(error_models.items(), key=lambda x: -x[1]):
